INSERT INTO Notification (NoID, Content, SentDate) VALUES
(1, N'Cảm ơn bạn đã quan tâm đến iPhone! Khám phá ngay các ưu đãi đặc biệt dành riêng cho bạn.', '2024-01-15 09:30:00'),
(2, N'Đơn hàng iPhone 15 Pro của bạn đã được xác nhận và đang được chuẩn bị. Theo dõi đơn hàng tại đây.', '2024-01-16 14:20:00'),
(3, N'iPhone 14 Pro Max đang có chương trình giảm giá 10% cho khách hàng thân thiết. Mua ngay kẻo lỡ!', '2024-01-17 11:00:00'),
(4, N'3 đơn hàng iPhone của bạn đã được giao thành công. Cảm ơn bạn đã tin tưởng và ủng hộ chúng tôi!', '2024-01-18 16:45:00'),
(5, N'Phụ kiện chính hãng Apple đang được giảm giá sốc khi mua kèm iPhone. Khám phá ngay!', '2024-01-19 10:15:00'),
